function stroke(x, col, tr)
    local s = New("\x55\x49\x53\x74\x72\x6f\x6b\x65", { Color = col or C.border, Transparency = tr or .55, Thickness = 1, Parent = x })
    local g = New("\x55\x49\x47\x72\x61\x64\x69\x65\x6e\x74", { Parent = s, Rotation = 35, Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(70,74,80)),
