        or string.find(teamName, "\x77\x61\x69\x74\x69\x6e\x67", 1, true) then
        return true
    end

    local containers = { player, player.Character }
    for _, container in ipairs(containers) do
        if container then
            for key, value in pairs(container:GetAttributes()) do
                local k = string.lower(tostring(key))
                if (string.find(k, "\x69\x6e\x72\x6f\x75\x6e\x64", 1, true) or string.find(k, "\x69\x6e\x67\x61\x6d\x65", 1, true)
