                    or string.find(k, "\x6c\x6f\x63\x61\x74\x69\x6f\x6e", 1, true) or string.find(k, "\x70\x6c\x61\x63\x65", 1, true) then
                    local textValue = string.lower(tostring(value))
                    if string.find(textValue, "\x6c\x6f\x62\x62\x79", 1, true)
                        or string.find(textValue, "\x73\x70\x65\x63\x74\x61\x74", 1, true)
