                        maybeRoleReset()
                        local parts = getCoinParts()
                        if #parts > 0 then
                            lastMapCF = CFrame.new(parts[1].Position + Vector3.new(0, 5, 0))
                        end
                        if #parts == 0 then
                            lastCoin = nil
                            goHome()
                            setStatus("\x52\x65\x74\x75\x72\x6e\x20\x54\x6f\x20" .. fopt.ret)
                            task.wait(0.45)
                            continue
                        end
                        if murdTooClose() then
