function consumeData(data, fullSnapshot)
    if typeof(data) ~= "\x74\x61\x62\x6c\x65" then return false end
    local records = (typeof(data.Players) == "\x74\x61\x62\x6c\x65" and data.Players) or (typeof(data.players) == "\x74\x61\x62\x6c\x65" and data.players) or data
    local lookup = {}
    for key, info in pairs(records) do
        local keyText = string.lower(tostring(key))
        lookup[keyText] = info
        if typeof(info) == "\x74\x61\x62\x6c\x65" then
            for _, identity in ipairs({ info.Name, info.PlayerName, info.Username, info.UserId, info.UserID, info.Id, info.PlayerId }) do
                if identity ~= nil then lookup[string.lower(tostring(identity))] = info end
            end
        end
    end
    local function normalizeRole(info)
        if typeof(info) == "\x74\x61\x62\x6c\x65" then
            if info.Dead == true or info.Killed == true or info.IsDead == true or info.Alive == false then return "\x64\x65\x61\x64" end
            info = info.Role or info.role or info.CurrentRole or info.currentRole or info.Team or info.team or info.Class
        end
        local value = string.lower(tostring(info or "\x69\x6e\x6e\x6f\x63\x65\x6e\x74")):gsub("\x5b\x25\x73\x5f\x25\x2d\x5d", "")
        if string.find(value, "\x6d\x75\x72\x64\x65\x72", 1, true) or string.find(value, "\x6b\x69\x6c\x6c\x65\x72", 1, true) then return "\x6d\x75\x72\x64\x65\x72\x65\x72" end
        if string.find(value, "\x73\x68\x65\x72\x69\x66\x66", 1, true) then return "\x73\x68\x65\x72\x69\x66\x66" end
        if string.find(value, "\x68\x65\x72\x6f", 1, true) then return "\x68\x65\x72\x6f" end
        if string.find(value, "\x64\x65\x61\x64", 1, true) or string.find(value, "\x6b\x69\x6c\x6c\x65\x64", 1, true) then return "\x64\x65\x61\x64" end
        return "\x69\x6e\x6e\x6f\x63\x65\x6e\x74"
    end
    local foundMurderer, foundSheriff, foundHero, received, changed = nil, nil, nil, false, false
    for _, player in ipairs(getPlayers()) do
        local info = lookup[string.lower(player.Name)] or lookup[tostring(player.UserId)] or lookup[string.lower(tostring(player.UserId))]
        if info ~= nil then
            received = true
            playerData[player.UserId] = info
            local resolved = normalizeRole(info)
            if roleCache[player.UserId] ~= resolved then
                roleCache[player.UserId], changed = resolved, true
                if autoNotifyRoles and (resolved == "\x6d\x75\x72\x64\x65\x72\x65\x72" or resolved == "\x73\x68\x65\x72\x69\x66\x66" or resolved == "\x68\x65\x72\x6f") and announcedRoles[player.UserId] ~= resolved then
                    announcedRoles[player.UserId] = resolved
                    notify(player.Name .. "\x20\x69\x73\x20" .. string.upper(resolved), 5)
                end
            end
            if resolved == "\x6d\x75\x72\x64\x65\x72\x65\x72" then foundMurderer = player
            elseif resolved == "\x73\x68\x65\x72\x69\x66\x66" then foundSheriff = player
            elseif resolved == "\x68\x65\x72\x6f" then foundHero = player end
        elseif fullSnapshot and roleCache[player.UserId] ~= "\x69\x6e\x6e\x6f\x63\x65\x6e\x74" then
            roleCache[player.UserId], changed = "\x69\x6e\x6e\x6f\x63\x65\x6e\x74", true
        end
    end
    local previousMurderer, previousSheriff, previousHero = murderer, sheriff, hero
    if fullSnapshot then
        murderer, sheriff, hero = foundMurderer, foundSheriff, foundHero
    else
        murderer, sheriff, hero = foundMurderer or murderer, foundSheriff or sheriff, foundHero or hero
    end
    if foundMurderer then setTarget(foundMurderer) end
    if previousMurderer ~= murderer or previousSheriff ~= sheriff or previousHero ~= hero then changed = true end
    if changed then
        local bus = getgenv().__NoirV4RoleBus
        if bus and bus.Emit then bus:Emit() end
    end
    return received
end
