end
function updatePing()
    pcall(function()
        local network = Stats:FindFirstChild("\x4e\x65\x74\x77\x6f\x72\x6b")
        local items = network and network:FindFirstChild("\x53\x65\x72\x76\x65\x72\x53\x74\x61\x74\x73\x49\x74\x65\x6d")
        local pingItem = items and items:FindFirstChild("\x44\x61\x74\x61\x20\x50\x69\x6e\x67")
        if pingItem then
            local measured = pingItem:GetValue() / 1000
            if measured > 0 and measured < 2 then cachedPing = cachedPing * 0.7 + measured * 0.3 end
        end
    end)
end

function getAimPart(player)
    local char = player and player.Character
    if not char then return nil end
    local partName = config.hitPart
    if partName == "\x52\x61\x6e\x64\x6f\x6d" then
        local opts = { "\x48\x65\x61\x64", "\x55\x70\x70\x65\x72\x54\x6f\x72\x73\x6f", "\x4c\x6f\x77\x65\x72\x54\x6f\x72\x73\x6f", "\x48\x75\x6d\x61\x6e\x6f\x69\x64\x52\x6f\x6f\x74\x50\x61\x72\x74" }
        partName = opts[math.random(#opts)]
    end
    local part = char:FindFirstChild(partName)
    if not part then part = char:FindFirstChild("\x48\x75\x6d\x61\x6e\x6f\x69\x64\x52\x6f\x6f\x74\x50\x61\x72\x74") or char.PrimaryPart end
    return part
end
function inFOV(player)
    if config.fovSize <= 0 then return true end
    local cam = Workspace.CurrentCamera
    local part = getAimPart(player)
    if not cam or not part then return false end
    local screen = cam:WorldToViewportPoint(part.Position)
    local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
    return (Vector2.new(screen.X, screen.Y) - center).Magnitude <= config.fovSize / 2
end
function passesFilters(player, trusted)
    if player == nil or player == LocalPlayer then return false end
    if not validTarget(player) then return false end
    if not trusted and playerIsInLobby(player) then return false end
    if isFriend(player) then return false end
    if config.maxDistance > 0 and distanceTo(player) > config.maxDistance then return false end
    return true
end
function selectTarget(mode)
    mode = mode or config.targetMode
    if mode == "\x4d\x75\x72\x64\x65\x72\x65\x72" then return passesFilters(murderer, true) and murderer or nil end
    if mode == "\x53\x68\x65\x72\x69\x66\x66" then return passesFilters(sheriff, true) and sheriff or nil end
    if mode == "\x48\x65\x72\x6f" then return passesFilters(hero, true) and hero or nil end
    if mode == "\x53\x65\x6c\x65\x63\x74\x65\x64" then
        local p = config.selectedPlayer and Players:FindFirstChild(config.selectedPlayer)
        return passesFilters(p, true) and p or nil
    end
    if mode == "\x4e\x65\x61\x72\x65\x73\x74" then
        local best, bd
        for _, p in ipairs(getPlayers()) do
            if passesFilters(p) then local d = distanceTo(p); if not bd or d < bd then best, bd = p, d end end
        end
        return best
    end
    if mode == "\x43\x72\x6f\x73\x73\x68\x61\x69\x72" then
        local cam = Workspace.CurrentCamera
        local best, bd
        if cam then
            local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
            for _, p in ipairs(getPlayers()) do
                if passesFilters(p) then
                    local part = getAimPart(p)
                    if part then
                        local screen = cam:WorldToViewportPoint(part.Position)
                        if screen.Z > 0 then
                            local d = (Vector2.new(screen.X, screen.Y) - center).Magnitude
                            if not bd or d < bd then best, bd = p, d end
                        end
                    end
                end
            end
        end
        return best
    end
    if mode == "\x4c\x6f\x77\x65\x73\x74\x20\x48\x65\x61\x6c\x74\x68" then
        local best, bh
        for _, p in ipairs(getPlayers()) do
            if passesFilters(p) then
                local hum = p.Character and p.Character:FindFirstChildWhichIsA("\x48\x75\x6d\x61\x6e\x6f\x69\x64")
                local h = hum and hum.Health or math.huge
                if not bh or h < bh then best, bh = p, h end
            end
        end
        return best
    end
    if mode == "\x52\x61\x6e\x64\x6f\x6d" then
        local list = {}
        for _, p in ipairs(getPlayers()) do if passesFilters(p) then list[#list + 1] = p end end
