    local function mix(key) return a[key] + (b[key] - a[key]) * alpha end
    return { Sim = math.floor(mix("\x53\x69\x6d") + 0.5), Interval = math.floor(mix("\x49\x6e\x74\x65\x72\x76\x61\x6c") + 0.5),
