        local mirror = noirMirrorControls[controlKey]
        if type(mirror) == "\x74\x61\x62\x6c\x65" and type(mirror.SetValue) == "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then pcall(mirror.SetValue, mirror, pingMs)
