    if typeof(remote) ~= "\x49\x6e\x73\x74\x61\x6e\x63\x65" or not remote:IsA("\x52\x65\x6d\x6f\x74\x65\x45\x76\x65\x6e\x74") then return false end
    if remote.Name ~= "\x4b\x6e\x69\x66\x65\x54\x68\x72\x6f\x77\x6e" then return false end
    if typeof(args[1]) ~= "\x43\x46\x72\x61\x6d\x65" or typeof(args[2]) ~= "\x43\x46\x72\x61\x6d\x65" then return false end
