local presetNames
function savePreset()
    if type(writefile) ~= "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then notify("\x45\x78\x65\x63\x75\x74\x6f\x72\x20\x64\x6f\x65\x73\x20\x6e\x6f\x74\x20\x73\x75\x70\x70\x6f\x72\x74\x20\x77\x72\x69\x74\x65\x66\x69\x6c\x65", 4) return end
    ensurePresetFolder()
    local ok, encoded = pcall(function() return HttpService:JSONEncode(exportRevertConfig()) end)
    if ok then
        local wrote, err = pcall(writefile, PRESET_FOLDER .. "\x2f" .. cleanPresetName(presetName) .. "\x2e\x70\x72\x65\x73\x65\x74", xorPreset(encoded))
        if wrote then
            notify("\x50\x72\x65\x73\x65\x74\x20\x73\x61\x76\x65\x64\x3a\x20" .. cleanPresetName(presetName), 3)
            if presetDropdown and presetDropdown.Refresh then presetDropdown:Refresh(presetNames(), cleanPresetName(presetName)) end
        else notify("\x50\x72\x65\x73\x65\x74\x20\x73\x61\x76\x65\x20\x66\x61\x69\x6c\x65\x64\x3a\x20" .. tostring(err), 4) end
    else notify("\x50\x72\x65\x73\x65\x74\x20\x65\x6e\x63\x6f\x64\x65\x20\x66\x61\x69\x6c\x65\x64", 4) end
end
function loadPreset()
    if type(readfile) ~= "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then notify("\x45\x78\x65\x63\x75\x74\x6f\x72\x20\x64\x6f\x65\x73\x20\x6e\x6f\x74\x20\x73\x75\x70\x70\x6f\x72\x74\x20\x72\x65\x61\x64\x66\x69\x6c\x65", 4) return end
    local path = PRESET_FOLDER .. "\x2f" .. cleanPresetName(presetName) .. "\x2e\x70\x72\x65\x73\x65\x74"
    local ok, decoded = pcall(function()
        local raw = readfile(path)
        return HttpService:JSONDecode(xorPreset(raw))
    end)
    if ok and applyRevertConfig(decoded) then
        if type(syncRevertControls) == "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then syncRevertControls() end
        notify("\x50\x72\x65\x73\x65\x74\x20\x6c\x6f\x61\x64\x65\x64\x3a\x20" .. cleanPresetName(presetName), 3)
    else notify("\x50\x72\x65\x73\x65\x74\x20\x6e\x6f\x74\x20\x66\x6f\x75\x6e\x64\x20\x6f\x72\x20\x69\x6e\x76\x61\x6c\x69\x64\x3a\x20" .. cleanPresetName(presetName), 4) end
end
presetNames = function()
    local names = { "\x64\x65\x66\x61\x75\x6c\x74" }
    if type(listfiles) == "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then
        ensurePresetFolder()
        local ok, files = pcall(listfiles, PRESET_FOLDER)
        if ok and typeof(files) == "\x74\x61\x62\x6c\x65" then
            for _, file in ipairs(files) do
                local normalized = tostring(file):gsub("\x5c", "\x2f")
                local name = normalized:match("\x28\x5b\x5e\x2f\x5d\x2b\x29\x25\x2e\x70\x72\x65\x73\x65\x74\x24")
                if name and not table.find(names, name) then names[#names + 1] = name end
            end
        end
    end
    table.sort(names)
    return names
end

 
