local function getDroppedGunParts()
    local now = os.clock()
    local cached = gunUtilityState.cachedDropParts
    if not gunUtilityState.dropCacheDirty and now - gunUtilityState.dropCacheAt < 1.25 then
        local valid = {}
        for _, part in ipairs(cached) do if part and part.Parent then valid[#valid + 1] = part end end
        if #valid == #cached then return valid end
        gunUtilityState.dropCacheDirty = true
    end
    local candidates, seen = {}, {}
    local function add(part, priority)
        if not part or not part:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") or seen[part] then return end
        seen[part] = true
        candidates[#candidates + 1] = { part = part, priority = priority }
    end
    local function scan(drop)
        if drop:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") then
            local ownTouch = drop:FindFirstChildWhichIsA("\x54\x6f\x75\x63\x68\x54\x72\x61\x6e\x73\x6d\x69\x74\x74\x65\x72")
            add(drop, ownTouch and 1 or (drop.Name == "\x48\x61\x6e\x64\x6c\x65" and 2 or 3))
        end
        for _, child in ipairs(drop:GetDescendants()) do
            if child:IsA("\x54\x6f\x75\x63\x68\x54\x72\x61\x6e\x73\x6d\x69\x74\x74\x65\x72") and child.Parent and child.Parent:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") then add(child.Parent, 1)
            elseif child:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") and child.Name == "\x48\x61\x6e\x64\x6c\x65" then add(child, 2)
            elseif child:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") and child.Name == "\x47\x75\x6e\x44\x72\x6f\x70" then add(child, 3)
            elseif child:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") then add(child, 4) end
        end
    end
    for _, instance in ipairs(Workspace:GetDescendants()) do if instance.Name == "\x47\x75\x6e\x44\x72\x6f\x70" then scan(instance) end end
    table.sort(candidates, function(a, b) return a.priority < b.priority end)
    local parts = table.create(#candidates)
    for index, candidate in ipairs(candidates) do parts[index] = candidate.part end
    gunUtilityState.cachedDropParts, gunUtilityState.dropCacheAt, gunUtilityState.dropCacheDirty = parts, now, false
    return parts
end
 
