    if gunUtilityState.bindGui then gunUtilityState.bindGui:Destroy() end
    gunUtilityState.bindGui, gunUtilityState.bindButton = nil, nil
    for _, parent in ipairs({guiParent, CoreGui, LocalPlayer:FindFirstChildOfClass("\x50\x6c\x61\x79\x65\x72\x47\x75\x69")}) do
        if typeof(parent) == "\x49\x6e\x73\x74\x61\x6e\x63\x65" then
            local stale = parent:FindFirstChild("\x4e\x6f\x69\x72\x47\x72\x61\x62\x47\x75\x6e\x42\x69\x6e\x64\x42\x75\x74\x74\x6f\x6e")
            if stale then stale:Destroy() end
        end
    end
end

