            local label = button:FindFirstChild("\x54\x65\x78\x74")
            if label then label.Text = universalState.invisible and "\x49\x6e\x76\x69\x73\x69\x62\x6c\x65\x0a\x4f\x4e" or "\x49\x6e\x76\x69\x73\x69\x62\x6c\x65\x0a\x4f\x46\x46" end
        end

        local function setInvisible(enabled)
