            applyInvisible()
            updateInvisibleBindText()
        end

        local function removeInvisibleBindButton()
            disconnectAll(universalState.invisibleBindConnections)
            if universalState.invisibleBindGui then universalState.invisibleBindGui:Destroy() end
            universalState.invisibleBindGui, universalState.invisibleBindButton = nil, nil
            for _, parent in ipairs({ guiParent, CoreGui, LocalPlayer:FindFirstChildOfClass("\x50\x6c\x61\x79\x65\x72\x47\x75\x69") }) do
                if typeof(parent) == "\x49\x6e\x73\x74\x61\x6e\x63\x65" then
                    local stale = parent:FindFirstChild("\x4e\x6f\x69\x72\x49\x6e\x76\x69\x73\x69\x62\x6c\x65\x42\x69\x6e\x64\x42\x75\x74\x74\x6f\x6e")
                    if stale then stale:Destroy() end
                end
            end
        end

        local function updateInvisibleBindButtonSize()
            local button, camera = universalState.invisibleBindButton, Workspace.CurrentCamera
            if not button or not camera then return end
            local screen = camera.ViewportSize
            local heightScale = universalState.invisibleBindSize
            button.Size = UDim2.new(heightScale * (screen.Y / math.max(screen.X, 1)), 0, heightScale, 0)
        end

        local function createInvisibleBindButton()
            if universalState.invisibleBindButton then return end
            removeInvisibleBindButton()
            local parent = guiParent
            if typeof(parent) ~= "\x49\x6e\x73\x74\x61\x6e\x63\x65" then parent = LocalPlayer:WaitForChild("\x50\x6c\x61\x79\x65\x72\x47\x75\x69") end
            local bindGui = Instance.new("\x53\x63\x72\x65\x65\x6e\x47\x75\x69")
            bindGui.Name, bindGui.ResetOnSpawn, bindGui.IgnoreGuiInset, bindGui.DisplayOrder = "\x4e\x6f\x69\x72\x49\x6e\x76\x69\x73\x69\x62\x6c\x65\x42\x69\x6e\x64\x42\x75\x74\x74\x6f\x6e", false, true, 82
