            for _, instance in ipairs(character:GetDescendants()) do
                if instance:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") then antiFlingTrackPart(instance) end
            end
            character.DescendantAdded:Connect(function(instance)
                if instance:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") then antiFlingTrackPart(instance) end
            end)
